describe('App：壳层布局与折叠形态（AC-1/AC-2/AC-7）', () => {
  beforeEach(() => {
    // 路由化后 App 自含 HashRouter（design D6）：jsdom location 跨用例存活，
    // 上一用例残留的 hash 会改变下一用例启动路由初态，先重置
    window.location.hash = '';
    getVersionMock.mockReset();
    invokeMock.mockReset();
