    fireEvent.click(await screen.findByTestId('explore-promote-trigger'));

    await screen.findByTestId('explore-promote-error');
    expect(screen.getByTestId<HTMLButtonElement>('explore-promote-trigger').disabled).toBe(false);
  });
});
