// ---------------------------------------------------------------------------

describe('ExploreView：分组派生下的根切换与 id 桥回归（AC-8）', () => {
  const ROOT2 = 'C:\\demo\\beta';

  it('边界：根切换落清单后新根记录按分组呈现（旧根条目不在场）', async () => {
    const betaActive = { ...record(9, 'beta-active', '乙根进行中'), root: ROOT2 };
    const betaPromoted = {
      ...record(8, 'beta-promoted', '乙根已转'),
      root: ROOT2,
      promotedTo: 'chg-2',
